import{_ as a,c as e,o as i,a0 as r}from"./chunks/framework.DKRgXLPU.js";const o=JSON.parse('{"title":"Structuring Your Practice","description":"Design practice sessions that maximize improvement. Learn how to structure training time for optimal skill development in pétanque.","frontmatter":{"title":"Structuring Your Practice","description":"Design practice sessions that maximize improvement. Learn how to structure training time for optimal skill development in pétanque."},"headers":[],"relativePath":"es/blog/practice-structure.md","filePath":"es/blog/practice-structure.md"}');const t=a({name:"es/blog/practice-structure.md"},[["render",function(a,o,t,n,s,l){return i(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="estructurando-su-practica" tabindex="-1">Estructurando su práctica <a class="header-anchor" href="#estructurando-su-practica" aria-label="Permalink to &quot;Estructurando su práctica&quot;">​</a></h1><p>No todas las prácticas son iguales. Dos jugadores pueden pasar las mismas horas en el terreno y observar mejoras muy diferentes. La diferencia suele radicar en cómo se estructura la práctica.</p><h2 id="el-problema-de-la-practica-no-estructurada" tabindex="-1">El problema de la práctica no estructurada <a class="header-anchor" href="#el-problema-de-la-practica-no-estructurada" aria-label="Permalink to &quot;El problema de la práctica no estructurada&quot;">​</a></h2><p>La mayoría de las prácticas recreativas se ven así:</p><ul><li>Aparece, lanza algunas petancas</li><li>Juega algunos juegos casuales</li><li>Chatea con amigos</li><li>Ir a casa</li></ul><p>Esto es agradable, pero ineficiente para mejorar. Sin estructura, usted:</p><ul><li>Repite patrones cómodos</li><li>Evitar las debilidades</li><li>Perder oportunidades para un desarrollo enfocado</li><li>No se puede seguir el progreso</li></ul><h2 id="principios-de-una-practica-eficaz" tabindex="-1">Principios de una práctica eficaz <a class="header-anchor" href="#principios-de-una-practica-eficaz" aria-label="Permalink to &quot;Principios de una práctica eficaz&quot;">​</a></h2><h3 id="_1-practica-con-proposito" tabindex="-1">1. Práctica con propósito <a class="header-anchor" href="#_1-practica-con-proposito" aria-label="Permalink to &quot;1. Práctica con propósito&quot;">​</a></h3><p>Cada sesión debe tener un propósito claro:</p><ul><li>¿En qué estoy trabajando hoy?</li><li>¿Cómo se ve el éxito?</li><li>¿Cómo sabré si he mejorado?</li></ul><h3 id="_2-dificultad-deliberada" tabindex="-1">2. Dificultad deliberada <a class="header-anchor" href="#_2-dificultad-deliberada" aria-label="Permalink to &quot;2. Dificultad deliberada&quot;">​</a></h3><p>La práctica debería desafiarte:</p><ul><li>Trabaja al límite de tus capacidades</li><li>Incluir elementos que sean difíciles</li><li>Evite la repetición pura de la zona de confort</li></ul><h3 id="_3-retroalimentacion-inmediata" tabindex="-1">3. Retroalimentación inmediata <a class="header-anchor" href="#_3-retroalimentacion-inmediata" aria-label="Permalink to &quot;3. Retroalimentación inmediata&quot;">​</a></h3><p>Necesitas saber cómo lo estás haciendo:</p><ul><li>Realizar un seguimiento de los resultados de los simulacros</li><li>Utilice vídeo cuando sea posible</li><li>Obtenga aportes de los socios de capacitación</li></ul><h3 id="_4-atencion-enfocada" tabindex="-1">4. Atención enfocada <a class="header-anchor" href="#_4-atencion-enfocada" aria-label="Permalink to &quot;4. Atención enfocada&quot;">​</a></h3><p>Calidad sobre cantidad:</p><ul><li>Concentración total durante la práctica</li><li>Las sesiones más cortas y enfocadas son mejores que las largas y distraídas.</li><li>El compromiso mental es esencial</li></ul><h2 id="estructura-de-la-sesion" tabindex="-1">Estructura de la sesión <a class="header-anchor" href="#estructura-de-la-sesion" aria-label="Permalink to &quot;Estructura de la sesión&quot;">​</a></h2><h3 id="calentamiento-10-15-minutos" tabindex="-1">Calentamiento (10-15 minutos) <a class="header-anchor" href="#calentamiento-10-15-minutos" aria-label="Permalink to &quot;Calentamiento (10-15 minutos)&quot;">​</a></h3><p><strong>Físico:</strong></p><ul><li>Movimiento ligero</li><li>Preparación de brazos y hombros</li><li>Aumento gradual de la intensidad</li></ul><p><strong>Mental:</strong></p><ul><li>Transición de la vida cotidiana</li><li>Establecer intención para la sesión</li><li>Comience a centrar la atención</li></ul><h3 id="trabajo-tecnico-20-30-minutos" tabindex="-1">Trabajo técnico (20-30 minutos) <a class="header-anchor" href="#trabajo-tecnico-20-30-minutos" aria-label="Permalink to &quot;Trabajo técnico (20-30 minutos)&quot;">​</a></h3><p>Centrarse en habilidades específicas:</p><ul><li>Práctica de técnica aislada</li><li>Ejercicios dirigidos a las debilidades</li><li>Repetición con atención</li></ul><p><strong>Ejemplos de áreas de enfoque:</strong></p><ul><li>Precisión de apuntado a distancias específicas</li><li>Disparando desde diferentes ángulos</li><li>Tipos de lanzamiento específicos (plombée, portée, etc.)</li></ul><h3 id="practica-aplicada-20-30-minutos" tabindex="-1">Práctica aplicada (20-30 minutos) <a class="header-anchor" href="#practica-aplicada-20-30-minutos" aria-label="Permalink to &quot;Práctica aplicada (20-30 minutos)&quot;">​</a></h3><p>Utilice habilidades en contextos realistas:</p><ul><li>Situaciones de juego simuladas</li><li>taladros de presión</li><li>Práctica de toma de decisiones</li></ul><h3 id="enfriamiento-10-minutos" tabindex="-1">Enfriamiento (10 minutos) <a class="header-anchor" href="#enfriamiento-10-minutos" aria-label="Permalink to &quot;Enfriamiento (10 minutos)&quot;">​</a></h3><p><strong>Físico:</strong></p><ul><li>Proyección de luz</li><li>Extensión</li></ul><p><strong>Mental:</strong></p><ul><li>Revisa lo que aprendiste</li><li>Áreas de notas para trabajo futuro</li><li>Transición fuera del modo de práctica</li></ul><h2 id="tipos-de-sesiones-de-practica" tabindex="-1">Tipos de sesiones de práctica <a class="header-anchor" href="#tipos-de-sesiones-de-practica" aria-label="Permalink to &quot;Tipos de sesiones de práctica&quot;">​</a></h2><h3 id="sesion-de-desarrollo-de-habilidades" tabindex="-1">Sesión de desarrollo de habilidades <a class="header-anchor" href="#sesion-de-desarrollo-de-habilidades" aria-label="Permalink to &quot;Sesión de desarrollo de habilidades&quot;">​</a></h3><p>Enfoque: Desarrollar o perfeccionar técnicas específicas</p><ul><li>70% ejercicios técnicos</li><li>20% práctica aplicada</li><li>10% de calentamiento/enfriamiento</li></ul><h3 id="simulacion-de-competicion" tabindex="-1">Simulación de competición <a class="header-anchor" href="#simulacion-de-competicion" aria-label="Permalink to &quot;Simulación de competición&quot;">​</a></h3><p>Enfoque: Preparación para las condiciones del partido</p><ul><li>20% calentamiento con propósito</li><li>60% de juego similar a un partido con presión</li><li>20% de informe y ajuste</li></ul><h3 id="sesion-de-mantenimiento" tabindex="-1">Sesión de mantenimiento <a class="header-anchor" href="#sesion-de-mantenimiento" aria-label="Permalink to &quot;Sesión de mantenimiento&quot;">​</a></h3><p>Enfoque: Mantener las habilidades afiladas</p><ul><li>Trabajo equilibrado en todas las áreas</li><li>No hay un enfoque intenso en ninguna cosa</li><li>Disfrutable pero con propósito</li></ul><h3 id="sesion-de-recuperacion" tabindex="-1">Sesión de recuperación <a class="header-anchor" href="#sesion-de-recuperacion" aria-label="Permalink to &quot;Sesión de recuperación&quot;">​</a></h3><p>Enfoque: Práctica ligera después de la competición.</p><ul><li>Baja intensidad</li><li>Lanzamiento divertido</li><li>Reinicio mental</li></ul><h2 id="diseno-de-simulacros" tabindex="-1">Diseño de simulacros <a class="header-anchor" href="#diseno-de-simulacros" aria-label="Permalink to &quot;Diseño de simulacros&quot;">​</a></h2><p>Los ejercicios efectivos tienen:</p><h3 id="objetivos-claros" tabindex="-1">Objetivos claros <a class="header-anchor" href="#objetivos-claros" aria-label="Permalink to &quot;Objetivos claros&quot;">​</a></h3><p>¿Qué estás practicando específicamente?</p><h3 id="resultados-medibles" tabindex="-1">Resultados medibles <a class="header-anchor" href="#resultados-medibles" aria-label="Permalink to &quot;Resultados medibles&quot;">​</a></h3><p>¿Cómo se sigue el éxito?</p><h3 id="desafio-apropiado" tabindex="-1">Desafío apropiado <a class="header-anchor" href="#desafio-apropiado" aria-label="Permalink to &quot;Desafío apropiado&quot;">​</a></h3><p>Lo suficientemente fuerte como para estirarse, pero no tan fuerte como para no tener éxito.</p><h3 id="pertinencia" tabindex="-1">Pertinencia <a class="header-anchor" href="#pertinencia" aria-label="Permalink to &quot;Pertinencia&quot;">​</a></h3><p>Conectado a situaciones de juego reales</p><h3 id="progresion" tabindex="-1">Progresión <a class="header-anchor" href="#progresion" aria-label="Permalink to &quot;Progresión&quot;">​</a></h3><p>Formas de aumentar la dificultad a medida que mejoras</p><h2 id="ejercicios-de-muestra" tabindex="-1">Ejercicios de muestra <a class="header-anchor" href="#ejercicios-de-muestra" aria-label="Permalink to &quot;Ejercicios de muestra&quot;">​</a></h2><h3 id="precision-de-apuntado" tabindex="-1">Precisión de apuntado <a class="header-anchor" href="#precision-de-apuntado" aria-label="Permalink to &quot;Precisión de apuntado&quot;">​</a></h3><p><strong>Configuración:</strong> Objetivo a 8 metros <strong>Objetivo:</strong> Aterrizar a 30 cm del objetivo <strong>Pista:</strong> Tasa de éxito en más de 20 lanzamientos <strong>Progreso:</strong> Disminuir el tamaño del objetivo, aumentar la distancia</p><h3 id="consistencia-en-los-disparos" tabindex="-1">Consistencia en los disparos <a class="header-anchor" href="#consistencia-en-los-disparos" aria-label="Permalink to &quot;Consistencia en los disparos&quot;">​</a></h3><p><strong>Configuración:</strong> Bola de objetivo estacionaria <strong>Objetivo:</strong> Dar en el blanco <strong>Pista:</strong> Hits por cada 10 intentos <strong>Progreso:</strong> Variar ángulos, agregar movimiento</p><h3 id="simulacion-de-presion" tabindex="-1">Simulación de presión <a class="header-anchor" href="#simulacion-de-presion" aria-label="Permalink to &quot;Simulación de presión&quot;">​</a></h3><p><strong>Configuración:</strong> Debes hacer 3 en fila para &quot;ganar&quot; <strong>Objetivo:</strong> Completar la secuencia <strong>Pista:</strong> Se necesitan intentos <strong>Progreso:</strong> Aumentar la secuencia requerida</p><h2 id="planificacion-semanal" tabindex="-1">Planificación semanal <a class="header-anchor" href="#planificacion-semanal" aria-label="Permalink to &quot;Planificación semanal&quot;">​</a></h2><h3 id="ejemplo-de-semana-equilibrada" tabindex="-1">Ejemplo de semana equilibrada <a class="header-anchor" href="#ejemplo-de-semana-equilibrada" aria-label="Permalink to &quot;Ejemplo de semana equilibrada&quot;">​</a></h3><p><strong>Lunes:</strong> Desarrollo de habilidades (enfoque en señalar) <strong>Miércoles:</strong> Simulación de competición <strong>Viernes:</strong> Desarrollo de habilidades (enfoque en el tiro) <strong>Fin de semana:</strong> Partidos</p><h3 id="periodizacion" tabindex="-1">Periodización <a class="header-anchor" href="#periodizacion" aria-label="Permalink to &quot;Periodización&quot;">​</a></h3><p>Varía la intensidad a lo largo de la temporada:</p><p><strong>Fuera de temporada:</strong> Desarrollo intensivo de habilidades <strong>Pretemporada:</strong> Integración y simulación <strong>Temporada de competición:</strong> Mantenimiento y afilado <strong>Postemporada:</strong> Recuperación y reflexión</p><h2 id="errores-comunes" tabindex="-1">Errores comunes <a class="header-anchor" href="#errores-comunes" aria-label="Permalink to &quot;Errores comunes&quot;">​</a></h2><h3 id="demasiado-juego" tabindex="-1">Demasiado juego <a class="header-anchor" href="#demasiado-juego" aria-label="Permalink to &quot;Demasiado juego&quot;">​</a></h3><p>Jugar es divertido, pero no permite atacar las debilidades de manera eficiente.</p><h3 id="sin-seguimiento" tabindex="-1">Sin seguimiento <a class="header-anchor" href="#sin-seguimiento" aria-label="Permalink to &quot;Sin seguimiento&quot;">​</a></h3><p>Sin medición, no puedes saber si estás mejorando.</p><h3 id="evitando-debilidades" tabindex="-1">Evitando debilidades <a class="header-anchor" href="#evitando-debilidades" aria-label="Permalink to &quot;Evitando debilidades&quot;">​</a></h3><p>Practicamos naturalmente lo que se nos da bien. Oblígate a trabajar en tus debilidades.</p><h3 id="horario-inconsistente" tabindex="-1">Horario inconsistente <a class="header-anchor" href="#horario-inconsistente" aria-label="Permalink to &quot;Horario inconsistente&quot;">​</a></h3><p>La práctica esporádica produce resultados esporádicos.</p><h3 id="sin-practica-mental" tabindex="-1">Sin práctica mental <a class="header-anchor" href="#sin-practica-mental" aria-label="Permalink to &quot;Sin práctica mental&quot;">​</a></h3><p>La repetición física sin compromiso mental limita la mejora.</p><h2 id="hacer-que-la-practica-perdure" tabindex="-1">Hacer que la práctica perdure <a class="header-anchor" href="#hacer-que-la-practica-perdure" aria-label="Permalink to &quot;Hacer que la práctica perdure&quot;">​</a></h2><h3 id="antes-de-la-practica" tabindex="-1">Antes de la práctica <a class="header-anchor" href="#antes-de-la-practica" aria-label="Permalink to &quot;Antes de la práctica&quot;">​</a></h3><ul><li>Establecer intenciones claras</li><li>Prepárate mentalmente</li><li>Revisar notas de sesiones anteriores</li></ul><h3 id="durante-la-practica" tabindex="-1">Durante la práctica <a class="header-anchor" href="#durante-la-practica" aria-label="Permalink to &quot;Durante la práctica&quot;">​</a></h3><ul><li>Mantente concentrado</li><li>Resultados de la pista</li><li>Ajustar según sea necesario</li></ul><h3 id="despues-de-la-practica" tabindex="-1">Después de la práctica <a class="header-anchor" href="#despues-de-la-practica" aria-label="Permalink to &quot;Después de la práctica&quot;">​</a></h3><ul><li>Toma nota de lo que has aprendido</li><li>Identificar los próximos pasos</li><li>Celebrar el progreso</li></ul><h2 id="el-mito-de-las-10-000-horas" tabindex="-1">El mito de las 10.000 horas <a class="header-anchor" href="#el-mito-de-las-10-000-horas" aria-label="Permalink to &quot;El mito de las 10.000 horas&quot;">​</a></h2><p>No se trata sólo de horas, se trata de calidad. 1.000 horas de práctica deliberada superan a 10.000 horas de repetición sin sentido.</p><p>Estructura tu práctica con un propósito y cada hora contará más.</p><hr><p>| <em>Relacionado: <a href="/es/educacion/formacion/">Métodos de formación</a> | <a href="/es/educacion/entrenamiento/simulacros">Simulacros de entrenamiento</a> | <a href="/es/educacion/metas/">Establecimiento de metas</a></em> |</p>',100)])])}]]);export{o as __pageData,t as default};
